select

from ingestion_task
where id = #{taskId}
  and workspace_id = #{workspaceId}
  and kb_id = #{kbId}

select

from ingestion_task
where workspace_id = #{workspaceId}
  and kb_id = #{kbId}

  and status = #{status}

order by created_at desc, id desc
limit #{limit}

select
    iti.id, iti.task_id, iti.kb_id, iti.asset_id, iti.file_name, iti.file_hash, iti.source_url,
    iti.stage, iti.status, iti.progress, iti.dedupe_result, iti.error_code, iti.error_message,
    iti.created_at, iti.updated_at, iti.finished_at
from ingestion_task_item iti
inner join ingestion_task it on it.id = iti.task_id
where it.workspace_id = #{workspaceId}
  and it.kb_id = #{kbId}
  and it.id = #{taskId}
  and iti.id = #{itemId}

mapper.update:
update ingestion_task it
set it.total_count = (
        select count(1)
        from ingestion_task_item iti
        where iti.task_id = #{taskId}
    ),
    it.success_count = (
        select count(1)
        from ingestion_task_item iti
        where iti.task_id = #{taskId}
          and iti.status in ('SUCCESS', 'SKIPPED')
    ),
    it.failure_count = (
        select count(1)
        from ingestion_task_item iti
        where iti.task_id = #{taskId}
          and iti.status = 'FAILED'
    ),
    it.running_count = (
        select count(1)
        from ingestion_task_item iti
        where iti.task_id = #{taskId}
          and iti.status = 'RUNNING'
    ),
    it.status = case
        when (
            select count(1)
            from ingestion_task_item iti
            where iti.task_id = #{taskId}
              and iti.status in ('RUNNING', 'PENDING')
        ) > 0 then 'PENDING'
        when (
            select count(1)
            from ingestion_task_item iti
            where iti.task_id = #{taskId}
              and iti.status = 'FAILED'
        ) = 0 then 'SUCCESS'
        when (
            select count(1)
            from ingestion_task_item iti
            where iti.task_id = #{taskId}
              and iti.status in ('SUCCESS', 'SKIPPED')
        ) = 0 then 'FAILED'
        else 'PARTIAL_SUCCESS'
    end,
    it.updated_by = #{updatedBy},
    it.updated_at = #{updatedAt},
    it.finished_at = case
        when (
            select count(1)
            from ingestion_task_item iti
            where iti.task_id = #{taskId}
              and iti.status in ('RUNNING', 'PENDING')
        ) > 0 then null
        else #{updatedAt}
    end
where it.id = #{taskId}
  and it.workspace_id = #{workspaceId}
  and it.kb_id = #{kbId}
